	"origin" text NOT NULL,
	"state" jsonb,
	"label" jsonb,
	"created_at" timestamp DEFAULT now() NOT NULL,
	"updated_at" timestamp DEFAULT now() NOT NULL,
	CONSTRAINT "registrations_scope_key_uq" UNIQUE("scope_kind","scope_ref","key"),
	CONSTRAINT "registrations_scope_check" CHECK ("registrations"."scope_kind" IN ('genre', 'preset', 'session')),
